SELECT JSON_OBJECT('yield_route_id',o.`yield_route_id`,'observation_time',o.`observation_time`,'collected_at',o.`collected_at`,'tier_no',o.`tier_no`,'tier_min_amount',CAST(o.`tier_min_amount` AS CHAR),'tier_max_amount',CAST(o.`tier_max_amount` AS CHAR),'tier_mode',CAST(o.`tier_mode` AS CHAR),'rate',CAST(o.`rate` AS CHAR),'rate_kind',CAST(o.`rate_kind` AS CHAR),'rate_origin',CAST(o.`rate_origin` AS CHAR),'rate_mode',CAST(o.`rate_mode` AS CHAR),'reward_asset_keys',HEX(o.`reward_asset_keys`),'reward_component_rates',HEX(o.`reward_component_rates`),'entry_fee_rate',CAST(o.`entry_fee_rate` AS CHAR),'exit_fee_rate',CAST(o.`exit_fee_rate` AS CHAR),'fixed_penalty_rate',CAST(o.`fixed_penalty_rate` AS CHAR),'performance_fee_rate',CAST(o.`performance_fee_rate` AS CHAR),'entry_fee_amount',CAST(o.`entry_fee_amount` AS CHAR),'exit_fee_amount',CAST(o.`exit_fee_amount` AS CHAR),'fixed_fee_asset_key',CAST(o.`fixed_fee_asset_key` AS CHAR),'lock_seconds',o.`lock_seconds`,'unbonding_seconds',o.`unbonding_seconds`,'rule_principal_loss_mode',CAST(o.`rule_principal_loss_mode` AS CHAR),'fixed_principal_loss_rate',CAST(o.`fixed_principal_loss_rate` AS CHAR),'rule_eligibility',CAST(o.`rule_eligibility` AS CHAR),'eligibility_reason',CAST(o.`eligibility_reason` AS CHAR),'exposure_ratio',CAST(o.`exposure_ratio` AS CHAR),'capacity',CAST(o.`capacity` AS CHAR),'remaining_capacity',CAST(o.`remaining_capacity` AS CHAR),'tvl',CAST(o.`tvl` AS CHAR),'availability',CAST(o.`availability` AS CHAR),'block_height',o.`block_height`,'block_hash',CAST(o.`block_hash` AS CHAR),'finality',CAST(o.`finality` AS CHAR),'source_payload_hash',CAST(o.`source_payload_hash` AS CHAR),'pool_cash',CAST(o.`pool_cash` AS CHAR),'redemption_window_seconds',o.`redemption_window_seconds`) FROM crypto_market_info.yield_observation o INNER JOIN (SELECT yield_route_id,MAX(observation_time) t FROM crypto_market_info.yield_observation GROUP BY yield_route_id) x ON x.yield_route_id=o.yield_route_id AND x.t=o.observation_time
